package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.indexOfAnyBut
 */
public class StringUtils_indexOfAnyBut_TriageGen2Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAnyBut_NullStr() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut(null, "abc"));
    }

    @Test
    public void testIndexOfAnyBut_EmptyStr() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_NullSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", null));
    }

    @Test
    public void testIndexOfAnyBut_EmptySearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", ""));
    }

    @Test
    public void testIndexOfAnyBut_NoMatch() {
        // All characters in str are in searchChars
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", "abcde"));
    }

    @Test
    public void testIndexOfAnyBut_MatchAtStart() {
        // 'z' is not in 'abc'
        assertEquals(0, StringUtils.indexOfAnyBut("zabc", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_MatchInMiddle() {
        assertEquals(2, StringUtils.indexOfAnyBut("abzcd", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_MatchAtEnd() {
        assertEquals(3, StringUtils.indexOfAnyBut("abcx", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_SingleCharStr() {
        assertEquals(0, StringUtils.indexOfAnyBut("a", "b"));
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("a", "a"));
    }

    /**
     * Testing the High Surrogate branch logic.
     * Note: The implementation provided has a potential bug/logic quirk:
     * char ch2 = str.charAt(i * 1); 
     * This effectively sets ch2 = ch. 
     * If ch is a High Surrogate and is found in searchChars, 
     * but ch2 (which is the same char) is NOT found in searchChars, 
     * it returns i. However, since ch == ch2, the condition (chFound && !chFound) is impossible.
     * We will test the paths to ensure branch coverage.
     */
    @Test
    public void testIndexOfAnyBut_HighSurrogateBranch() {
        // A high surrogate character (e.g., \uD83D)
        String highSurrogateStr = "\uD83D\uDE00abc"; // 😀abc
        String searchChars = "\uD83Dabc"; 

        // This tests the 'if (i + 1 < strLen && Character.isHighSurrogate(ch))' path
        // In the provided code: ch2 = str.charAt(i * 1) -> ch2 is same as ch.
        // Therefore, if chFound is true, ch2.indexOf(ch) >= 0 is also true.
        // The 'if (chFound && searchChars.indexOf(ch2) < 0)' will be false.
        // It will fall through to the next loop iteration.

        // Testing standard path for surrogate
        assertEquals(3, StringUtils.indexOfAnyBut(highSurrogateStr, "\uD83D\uDE00ab"));
    }

    @Test
    public void testIndexOfAnyBut_AllCharsInSearch() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("aaaaa", "a"));
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("123", "123456"));
    }

    @Test
    public void testIndexOfAnyBut_SpecialChars() {
        assertEquals(0, StringUtils.indexOfAnyBut("!@#", "abc"));
        assertEquals(1, StringUtils.indexOfAnyBut("a!b", "ab"));
    }
}
